def crackSafe(n: int, k: int) -> str:
    seen = set()
    ans = []
    def dfs(node):
        for x in map(str, range(k)):
            edge = node + x
            if edge not in seen:
                seen.add(edge)
                dfs(edge[1:])
                ans.append(x)
    start = '0' * (n - 1)
    dfs(start)
    return start + ''.join(reversed(ans))

